INSERT INTO `facebook_settings` (`id`, `revision`, `rules_json`, `updated_at`) VALUES
(1, 1, '{\"categorize\":true,\"prepare_replies\":true,\"notify_comments\":true,\"templates\":{\"booking\":\"Thank you for your booking inquiry!\\n\\nWe offer 5-, 8-, 9-, and 10-guest rooms, as well as large-group accommodations and exclusive use of the entire building for groups of 88–100 guests.\\n\\nTo help us check availability, please send us your:\\n• Check-in and check-out dates\\n• Total number of guests\\n• Preferred room or accommodation\\n\\nPlease note: Your booking is only confirmed once our staff has contacted and confirmed it with you.\",\"rates\":\"Thank you for your inquiry about our rates!\\n\\nOur rates may vary depending on your dates, number of guests, room arrangement, and requested activities.\\n\\nTo provide you with the correct rate, please send us:\\n• Check-in and check-out dates\\n• Total number of guests\\n• Preferred accommodation\\n• Requested activities, if any\\n\\nATV, banana boat, and jet ski rentals are also available upon inquiry.\\n\\nOnce we receive your details, our team will prepare the appropriate quote for your stay.\",\"amenities\":\"Here’s what you can enjoy during your stay!\\n\\n🏠 Rooms & Entertainment\\n• Air-conditioned rooms\\n• Pet-friendly stays\\n• Free Wi-Fi with speeds of up to 800 Mbps\\n• Netflix, HBO Max, and Prime Video on the common TV\\n• LG XBOOM speaker with microphone\\n• Karaoke-friendly common area\\n\\n🍳 Kitchen & Outdoor Facilities\\n• Shared kitchen with utensils and rice cooker\\n• Common refrigerator\\n• Water dispenser\\n• Griller\\n• Tables and chairs\\n\\n🏖️ Activities & Additional Options\\n• ATV, banana boat, and jet ski rentals available upon inquiry\\n• Private pool option available for large groups upon request\\n\\nFeel free to message us if you’d like to know more about any of our amenities or available activities.\",\"location\":\"📍 Our Location\\n\\nOdidepse Beach Resort is located along Purok 8 Coastal Road, Brgy. Sto. Niño, San Felipe, Zambales.\\n\\n📌 Plus Code: 3355+4P\\n🏖️ Approximately a 25-second walk to the beach\\n🚗 Around 4 hours from Manila\\n\\n📍 Find us on Google Maps:\\nhttps:\\/\\/maps.app.goo.gl\\/wwsFkZsSMAjkNS4M8\",\"complaint\":\"We’re sorry to hear about your concern, and we appreciate you bringing it to our attention.\\n\\nPlease allow our admin team some time to review your message. We’ll do our best to assist you as soon as possible.\\n\\nSalamat po sa inyong pag-unawa at pasensya.\",\"general\":\"Thank you for contacting Odidepse Beach Resort!\\n\\nWe’re happy to assist you with rooms, rates, availability, amenities, activities, directions, and group arrangements.\\n\\nSabihin lamang po kung ano ang kailangan ninyo. For booking inquiries, please include your dates and number of guests so we can assist you faster.\\n\\nWe look forward to welcoming you to Odidepse Beach Resort!\"},\"keywords\":{\"booking\":[\"book\",\"booking\",\"reserve\",\"reservation\",\"availability\",\"available\",\"vacancy\",\"mag-book\",\"magpareserve\",\"may available\",\"bakante\"],\"rates\":[\"price\",\"rate\",\"rates\",\"cost\",\"how much\",\"magkano\",\"presyo\",\"bayad\"],\"amenities\":[\"pool\",\"wifi\",\"parking\",\"amenities\",\"kayak\",\"jetski\",\"activities\",\"pet\",\"pets\",\"may pool\",\"may wifi\",\"pwede pet\"],\"location\":[\"where\",\"location\",\"address\",\"direction\",\"directions\",\"saan\",\"paano pumunta\",\"malapit ba\",\"direksyon\"],\"complaint\":[\"complaint\",\"refund\",\"disappointed\",\"disappointing\",\"rude\",\"unsafe\",\"scam\",\"reklamo\",\"hindi maayos\",\"pangit ang serbisyo\"],\"general\":[]}}', '2026-09-13 03:50:32');
