('photos', '[{\"id\":\"room_0\",\"title\":\"Poolside, sea side\",\"alt\":\"The resort pool overlooking the sea\"},{\"id\":\"room_1\",\"title\":\"Room for everyone\",\"alt\":\"Bunk beds and a window in a resort room\"},{\"id\":\"room_2\",\"title\":\"Under an open sky\",\"alt\":\"The resort pool and open upper terrace\"},{\"id\":\"room_3\",\"title\":\"Settle right in\",\"alt\":\"A resort bunk room seen through its doorway\"},{\"id\":\"room_4\",\"title\":\"Stay together\",\"alt\":\"A shared room with multiple bunk beds\"},{\"id\":\"room_5\",\"title\":\"A different perspective\",\"alt\":\"An elevated view of the resort and pool\"},{\"id\":\"room_6\",\"title\":\"Easy mornings\",\"alt\":\"Bunk beds reflected in a room mirror\"},{\"id\":\"room_7\",\"title\":\"A quiet corner\",\"alt\":\"A resort room with bunk beds and an open doorway\"},{\"id\":\"room_8\",\"title\":\"Behind the door\",\"alt\":\"A wooden guest room door along the corridor\"},{\"id\":\"room_9\",\"title\":\"Up and away\",\"alt\":\"The indoor staircase and guest room doors\"},{\"id\":\"guest_0\",\"title\":\"Guests standing together by the sea\",\"alt\":\"Guests standing together by the sea\"},{\"id\":\"guest_1\",\"title\":\"Guests on a banana boat\",\"alt\":\"Guests on a banana boat\"},{\"id\":\"guest_2\",\"title\":\"Guests sharing a meal outdoors\",\"alt\":\"Guests sharing a meal outdoors\"},{\"id\":\"guest_3\",\"title\":\"A group gathered by the beach\",\"alt\":\"A group gathered by the beach\"},{\"id\":\"guest_4\",\"title\":\"Guests posing on off-road vehicles\",\"alt\":\"Guests posing on off-road vehicles\"},{\"id\":\"guest_5\",\"title\":\"A group sitting together at the resort\",\"alt\":\"A group sitting together at the resort\"},{\"id\":\"guest_6\",\"title\":\"Guests gathered around a dining table\",\"alt\":\"Guests gathered around a dining table\"},{\"id\":\"guest_7\",\"title\":\"A group posing near the shore\",\"alt\":\"A group posing near the shore\"},{\"id\":\"guest_8\",\"title\":\"Guests gathered beneath the trees\",\"alt\":\"Guests gathered beneath the trees\"},{\"id\":\"guest_9\",\"title\":\"A group posing by the beach at sunset\",\"alt\":\"A group posing by the beach at sunset\"},{\"id\":\"guest_10\",\"title\":\"Guests on off-road vehicles near the beach\",\"alt\":\"Guests on off-road vehicles near the beach\"}]'),
('reviews', '[{\"name\":\"The weekend crew\",\"type\":\"Friends’ getaway\",\"quote\":\"The kind of weekend we needed. Slow mornings, a dip in the pool, and so much time just catching up.\",\"rating\":5},{\"name\":\"A family by the sea\",\"type\":\"Family escape\",\"quote\":\"Our favorite part was being together. Plenty of photos, long conversations, and a sunset we wished would last a little longer.\",\"rating\":5},{\"name\":\"The sunset seekers\",\"type\":\"Coastal break\",\"quote\":\"We came for a change of scenery and left with a camera full of memories. Already dreaming of our next beach day.\",\"rating\":4}]');
